      sycl::ext::oneapi::this_work_item::get_sub_group(), sum,
      sycl::plus<float>{});
  for (int j = sycl::ext::oneapi::this_work_item::get_sub_group()
                   .get_local_linear_id();
       j < sliceSize; j += sycl::ext::oneapi::this_work_item::get_sub_group()
