  const float* x = src + i * sliceSize;
  float* y = dest + i * sliceSize;

  float max_ = x[0];
  for (int j = 0; j < sliceSize; j++) max_ = sycl::max(max_, x[j]);

  float sum = 0.0f;
  for (int j = 0; j < sliceSize; j++) sum += sycl::exp(x[j] - max_);

  for (int j = 0; j < sliceSize; j++) y[j] = sycl::exp(x[j] - max_) / sum;
